def map_stages(df):
    STAGE_OUTCOME = {
        "Proposal": "open",
        "Prospecting": "open",
        "Negotiation": "open",
        "Closed Lost": "lost",
        "Closed - Won": "won"
    }
    df["Outcome"] = df["Stage"].map(STAGE_OUTCOME).fillna("unknown")
    return df

